38	// StreamProcessor implements the logic for handling xDS streams to zTunnel.
39	// It is abstracted away from the primary stream initialization handler to
40	// promote decoupling and the handling multiple streams without a shared set of
41	// channels being required on the Server object.
42	type StreamProcessor struct {
43		stream         v3.AggregatedDiscoveryService_DeltaAggregatedResourcesServer
44		streamRecv     chan *v3.DeltaDiscoveryRequest
45		endpointRecv   chan *EndpointEvent
46		expectedNonce  map[string]struct{}
47		log            *slog.Logger
48		endpointSource EndpointEventSource
49	}
