51	// EndpointSource provides data for XDS server from different data sources in the agent.
52	type EndpointSource struct {
53		k8sCiliumEndpointsWatcher *watchers.K8sCiliumEndpointsWatcher
54		sp                        *StreamProcessor
55	}
