57	func NewEndpointSource(k *watchers.K8sCiliumEndpointsWatcher, sp *StreamProcessor) *EndpointSource {
58		return &EndpointSource{
59			k8sCiliumEndpointsWatcher: k,
60			sp:                        sp,
61		}
62	}
