71	func NewStreamProcessor(params *StreamProcessorParams) *StreamProcessor {
72		sp := &StreamProcessor{
73			stream:        params.Stream,
74			streamRecv:    params.StreamRecv,
75			endpointRecv:  params.EndpointEventRecv,
76			log:           params.Log,
77			expectedNonce: make(map[string]struct{}),
78		}
79		sp.endpointSource = NewEndpointSource(params.K8sCiliumEndpointsWatcher, sp)
80		return sp
81	}
