83	// convertCESToEndpointMap converts a CiliumEndpointSlice to a map of CiliumEndpoints
84	// keyed by namespace/name for easy lookup and comparison.
85	func convertCESToEndpointMap(ces *v2alpha1.CiliumEndpointSlice) map[string]*types.CiliumEndpoint {
86		result := make(map[string]*types.CiliumEndpoint, len(ces.Endpoints))
87		for _, coreCep := range ces.Endpoints {
88			cep := k8s.ConvertCoreCiliumEndpointToTypesCiliumEndpoint(&coreCep, ces.Namespace)
89			cepName := cep.Namespace + "/" + cep.Name
90			result[cepName] = cep
91		}
92		return result
93	}
94	
95	// computeEndpointDiff compares old and new endpoint maps and returns lists of
96	// endpoints that were added, updated, or removed.
97	func computeEndpointDiff(oldCEPs, newCEPs map[string]*types.CiliumEndpoint) (added, updated, removed []*types.CiliumEndpoint) {
98		// Find removed endpoints (in old but not in new)
99		for cepName, oldCEP := range oldCEPs {
100			if _, exists := newCEPs[cepName]; !exists {
101				removed = append(removed, oldCEP)
102			}
103		}
104	
105		// Find new or updated endpoints
106		for cepName, newCEP := range newCEPs {
107			if oldCEP, exists := oldCEPs[cepName]; !exists {
108				// New endpoint
109				added = append(added, newCEP)
110			} else if !oldCEP.DeepEqual(newCEP) {
111				// Updated endpoint
112				updated = append(updated, newCEP)
113			}
114		}
115	
116		return added, updated, removed
117	}
