159	func (es *EndpointSource) SubscribeToEndpointEvents(ctx context.Context, wg *sync.WaitGroup) {
160		if option.Config.EnableCiliumEndpointSlice {
161			newSliceEvents := es.k8sCiliumEndpointsWatcher.GetCiliumEndpointSliceResource().Events(ctx, resource.WithErrorHandler(resource.AlwaysRetry))
162			// Keep track of CEPs in each CES to detect deletions on updates
163			cesCache := make(map[resource.Key]map[string]*types.CiliumEndpoint)
164	
165			for e := range newSliceEvents {
166				if e.Kind == resource.Sync {
167					wg.Done()
168					e.Done(nil)
169					continue
170				}
171				if e.Object == nil {
172					e.Done(nil)
173					continue
174				}
175	
176				switch e.Kind {
177				case resource.Upsert:
178					es.handleCESUpsert(e.Object, cesCache, e.Key)
179				case resource.Delete:
180					es.handleCESDelete(e.Object, cesCache, e.Key)
181				}
182	
183				e.Done(nil)
184			}
185			return
186		}
187	
188		// TODO(hemanthmalla): How should retries be configured here ?
189		newEvents := es.k8sCiliumEndpointsWatcher.GetCiliumEndpointResource().Events(ctx, resource.WithErrorHandler(resource.AlwaysRetry))
190		for e := range newEvents {
191			switch e.Kind {
192			case resource.Upsert:
193				es.sp.endpointRecv <- &EndpointEvent{
194					Type:           CREATE,
195					CiliumEndpoint: e.Object,
196				}
197			case resource.Delete:
198				es.sp.endpointRecv <- &EndpointEvent{
199					Type:           REMOVED,
200					CiliumEndpoint: e.Object,
201				}
202			case resource.Sync:
203				wg.Done()
204			}
205			e.Done(nil)
206		}
207	}
