203	func ConvertCEPToCoreCEP(cep *cilium_v2.CiliumEndpoint) *cilium_v2alpha1.CoreCiliumEndpoint {
204		// Copy Networking field into core CEP
205		var epNetworking *cilium_v2.EndpointNetworking
206		if cep.Status.Networking != nil {
207			epNetworking = new(cilium_v2.EndpointNetworking)
208			cep.Status.Networking.DeepCopyInto(epNetworking)
209		}
210		var identityID int64 = 0
211		if cep.Status.Identity != nil {
212			identityID = cep.Status.Identity.ID
213		}
214		return &cilium_v2alpha1.CoreCiliumEndpoint{
215			Name:           cep.GetName(),
216			Networking:     epNetworking,
217			Encryption:     cep.Status.Encryption,
218			IdentityID:     identityID,
219			NamedPorts:     cep.Status.NamedPorts.DeepCopy(),
220			ServiceAccount: cep.Status.ServiceAccount,
221		}
222	}
