68	func K8sNamespaceToEnrolledNamespace(ns k8s.Namespace, deleted bool) (*EnrolledNamespace, statedb.DeriveResult) {
69		enrolled := true
70		if mtlsValue, exists := ns.Labels["io.cilium/mtls-enabled"]; !exists || mtlsValue != "true" {
71			enrolled = false
72		}
73		if deleted || !enrolled {
74			return &EnrolledNamespace{
75				Name:   ns.Name,
76				Status: reconciler.StatusPending(),
77			}, statedb.DeriveDelete
78		}
79		return &EnrolledNamespace{
80			Name:   ns.Name,
81			Status: reconciler.StatusPending(),
82		}, statedb.DeriveInsert
83	}
