			if ces.Namespace != namespace {
				continue
			}
			for i := range ces.Endpoints {
				eps = append(eps, k8s.ConvertCoreCiliumEndpointToTypesCiliumEndpoint(&ces.Endpoints[i], ces.Namespace))
